    t["$Comment"] = ("SkyWynn archipelago PROOF world (SkyyWorldGen %s, Zone-Archipelago-Spec step 0.3): a throwaway admin test world from the "
                     "WorldStructure %s - the summit isle + 4 outer islands, 2 land necks, a rock arch and a bridge gap. Made once by /zone proof, "
                     "then kept until an admin deletes universe/worlds/%s (server stopped). Never use /instances spawn for it. Deaths keep items."
                     % ("0.4", P["structure"], P["world"]))
