M(mhop, r"""
public Object apply(Object o) {
  if (this.ex != null && Thread.currentThread() == this.caller) {
    @PKG@.WgIsle.HOPPED.incrementAndGet();
    this.fn.pending = o;
    return @CF@.supplyAsync(this.fn, this.ex);
  }
  return @CF@.completedFuture(this.fn.apply(o));
}""")

