# Server Setup (World Gen): live switch + the islet counts read when the world is first made
# ---- 0.7.8 THE ZONE SPAWN REMAP TABLE (Balance P6 spec 8.2): families = the 14 ladder crops (base block + every growth-state block id
# "*Plant_Crop_<C>_Block_State_Definitions_<S>" - how vanilla world gen places wild crops, VERIFIED in Server/World/Default/**), the
# Mushroom collection's ids (Cap / Common / Flatcap / Glowing / Shelve), the 9 herbs (wild Plant_Crop_<Herb><g> + the planted _Block and its
# states) and the 34 tree species (natural parts only: Trunk, Trunk_Full, Branch_Corner / Long / Short, Roots, leaves + leaf variants).
# Slot keys: 0 base / _Block, 1-9 StageN, 15 StageFinal, 20 a wild herb, 30-35 the tree parts, 40 leaves, 41 a leaf variant, 50 mushroom.
RM_HERB_TIER = {1: 2, 2: 5, 3: 8}                 # spec 8.1: herb grades 1-2-3 = T2 / T5 / T8
RM_HERBS = ("Health", "Mana", "Stamina")
RM_TREE_PARTS = (("Trunk", 30), ("Trunk_Full", 31), ("Branch_Corner", 32), ("Branch_Long", 33), ("Branch_Short", 34), ("Roots", 35))
RM_MUSH_RE = re.compile(r"^Plant_Crop_Mushroom_(Cap|Common|Flatcap|Glowing|Shelve)_")


def _rm_stage_key(st):
    if st == "StageFinal":
        return 15
    _m = re.match(r"^Stage([1-9])$", st)
    return int(_m.group(1)) if _m else None


def _rm_table():
    fams, names = [], []       # fams: (name, kind 0 crop / 1 mushroom / 2 herb / 3 tree, tier, herb group or -1); names: (block id, fam, key)
    with zipfile.ZipFile(_sj6.assets_zip()) as _az8:
        _it8 = dict((n.rsplit("/", 1)[1][:-5], n) for n in _az8.namelist() if n.startswith("Server/Item/Items/") and n.endswith(".json"))

        def _states(iid):
            _j = json.loads(_az8.read(_it8[iid]).decode("utf-8-sig"))
            _bt = _j.get("BlockType") or {}
            assert _bt, "not a block: " + iid
            return list(((_bt.get("State") or {}).get("Definitions") or {}).keys())

        def _block_with_states(base, fi):
            assert base in _it8, "Assets.zip has no " + base
            names.append((base, fi, 0))
            for _s in _states(base):
                _k = _rm_stage_key(_s)
                assert _k is not None, "unknown growth state %s of %s" % (_s, base)
                names.append(("*%s_State_Definitions_%s" % (base, _s), fi, _k))
        for _i, _c in enumerate(TT.CROP_LADDER):
            if _c == "Mushroom":
                fams.append(("Mushroom", 1, _i + 1, -1))
                _mu = sorted(i for i in _it8 if RM_MUSH_RE.match(i))
                assert _mu and _mu[0] == "Plant_Crop_Mushroom_Cap_Brown", _mu[:3]
                for _id in _mu:
                    names.append((_id, len(fams) - 1, 50))
                    for _s in _states(_id):          # Glowing_Orange has an "Exploding" state - removed with its mushroom
                        names.append(("*%s_State_Definitions_%s" % (_id, _s), len(fams) - 1, 50))
                continue
            fams.append((_c, 0, _i + 1, -1))
            _block_with_states("Plant_Crop_%s_Block" % _c, len(fams) - 1)
        for _hg, _h in enumerate(RM_HERBS):
            for _g in (1, 2, 3):
                fams.append(("%s%d" % (_h, _g), 2, RM_HERB_TIER[_g], _hg))
                _w = "Plant_Crop_%s%d" % (_h, _g)
                assert _w in _it8 and not _states(_w), _w
                names.append((_w, len(fams) - 1, 20))
                _block_with_states(_w + "_Block", len(fams) - 1)
        for _t in sorted(TT.LOGS):
            for _sp in TT.LOGS[_t]:
                fams.append((_sp, 3, _t, -1))
                _fi = len(fams) - 1
                for _part, _k in RM_TREE_PARTS:
                    if "Wood_%s_%s" % (_sp, _part) in _it8:
                        names.append(("Wood_%s_%s" % (_sp, _part), _fi, _k))
                assert any(n[1] == _fi and n[2] == 30 for n in names), "no trunk for tree " + _sp
                if "Plant_Leaves_" + _sp in _it8:
                    names.append(("Plant_Leaves_" + _sp, _fi, 40))
                for _lv in sorted(i for i in _it8 if i.startswith("Plant_Leaves_%s_" % _sp)):
                    if any(_lv == "Plant_Leaves_" + _o or _lv.startswith("Plant_Leaves_%s_" % _o) for _ws in TT.LOGS.values() for _o in _ws
                           if _o != _sp and _o.startswith(_sp + "_")):
                        continue                         # another species' leaves (none today - guard)
                    names.append((_lv, _fi, 41))
    assert len(set(f[0].lower() for f in fams)) == len(fams), "family names must be unique"
    assert len(set(n[0] for n in names)) == len(names), "a block id in two families"
    return fams, names


