assert [RM_FAMS[i][0] for i in RM_TOP[:4]] == ["Maple", "Gumboab", "Redwood", "Sallow"], [RM_FAMS[i][0] for i in RM_TOP[:4]]
assert [RM_FAMS[i][0] for i in RM_OWN[12:]] == ["Potato", "Onion", "Mushroom"]
RM_SW_DEF, RM_Z5_DEF = 2, 70


def rm_auto(z, f, sw=RM_SW_DEF):
    """the Java WgZ2Isles.rmAutoCode in python (the printed table + the harness): target fam + 1, -1 air, -2 own, -3 Zone 5 rule, 0 = keep"""
    if sw < 0:
        return 0
    name, kind, tier, hg = RM_FAMS[f]
    if z == 4:
        return -3 if kind == 0 and f not in RM_OWN[12:15] else 0
    if kind == 1:
        return -1 if z <= 2 else 0
    w = 3 * (z + 1) + sw
    if tier <= w:
        return 0
    if kind == 0:
        return -2
    if kind == 2:
        best = [i for i, x in enumerate(RM_FAMS) if x[1] == 2 and x[3] == hg and x[2] <= w]
        return (max(best, key=lambda i: RM_FAMS[i][2]) + 1) if best else -1
    if kind == 3:
        return RM_TOP[z] + 1 if RM_TOP[z] >= 0 and RM_TOP[z] != f else 0
    return 0


def rm_text(z, sw=RM_SW_DEF):
    out = []
    for f in range(len(RM_FAMS)):
        c = rm_auto(z, f, sw)
        if c:
            out.append("%s>%s" % (RM_FAMS[f][0], {-1: "air", -2: "own", -3: "z5"}.get(c) or RM_FAMS[c - 1][0]))
    return ",".join(out)


