# THE OWNER of a chunk: the zone whose land box is nearest to the chunk's 32 x 32 square (a Voronoi split; zones are 900+ blocks apart);
# ties -> the lower zone; -1 = no land at all. Used by the generator, the reset, the tidy and the harness.
M(z2isl, r"""
public static int ownerOfBoxes(int[] b, int cx, int cz) {
  double x0 = cx * 32.0;
  double z0 = cz * 32.0;
  double x1 = x0 + 32.0;
  double z1 = z0 + 32.0;
  int best = 0 - 1;
  double bd = 1.0E30;
  for (int p = 0; p + 4 < b.length; p = p + 5) {
    double dx = Math.max(0.0, Math.max((double) b[p + 1] - x1, x0 - (double) b[p + 3]));
    double dz = Math.max(0.0, Math.max((double) b[p + 2] - z1, z0 - (double) b[p + 4]));
    double d = dx * dx + dz * dz;
    if (d < bd || (d == bd && b[p] < best)) { bd = d; best = b[p]; }
  }
  return best;
}""")
M(z2isl, "public static int ownerOf(@PKG@.WgZ2Layout L, int cx, int cz) { return L == null ? 0 - 1 : ownerOfBoxes(boxesOf(L), cx, cz); }")
