# the login decision (pure; the harness runs it): 0 = stay, 1 = to the Zone 1 landing now, 2 = ask SkyyIslands again later
# (fix round, critic 3: looks at 2 s, 6 s and 12 s - a fresh /island in that window is seen before anything is sent)
M(shome, r"""
public static int loginDecide(boolean on, boolean inDefault, int island, int step) {
  if (!on || !inDefault) return 0;
  if (island < 0) return 1;
  if (island == 1) return 0;
  if (step < 2) return 2;
  return 1;
}""")
M(shome, r"""
public static boolean isDefault(@WLD@ w) {
  if (w == null) return false;
  if (@PKG@.WgZones.worldIndex(w.getName()) >= 0) return false;
  try {
    @WLD@ d = @UNI@.get().getDefaultWorld();
    return d != null && (d == w || d.getName().equals(w.getName()));
  } catch (Throwable t) { return false; }
}""")
M(shome, r"""
public static void schedule(@PR@ pr, int step, long ms) {
  try { @HSV@.SCHEDULED_EXECUTOR.schedule(new @PKG@.WgSpawnHome(pr, step, false), ms, java.util.concurrent.TimeUnit.MILLISECONDS); }
  catch (Throwable t) { @PKG@.WgLog.warn("could not schedule the Zone 1 login trip: " + t); }
}""")
M(shome, r"""
public void route(@WLD@ w) {
  if (this.pr == null || !this.pr.isValid()) return;
  int d = loginDecide(@PKG@.WgCfg.SPAWN_ON, isDefault(w), islandOf(this.pr.getUuid()), this.step);
  if (d == 2) { schedule(this.pr, this.step + 1, this.step == 0 ? AGAIN_MS : LAST_MS); return; }
  if (d != 1) return;
  java.util.UUID wu = this.pr.getWorldUuid();                       // re-read right before sending: still in the default world?
  @WLD@ now = null;
  if (wu != null) now = @UNI@.get().getWorld(wu);
  if (now != w || !isDefault(now)) return;
  @REF@ ref = this.pr.getReference();
  if (ref == null || !ref.isValid()) return;
  @ST@ st = ref.getStore();
  if (st == null) return;
  if (send(st, ref, this.pr, w, "the login of a player without an island")) ROUTED.incrementAndGet();
}""")
M(shome, r"""
public void run() {
  try {
    if (this.pr == null || !this.pr.isValid()) return;
    java.util.UUID wu = this.pr.getWorldUuid();
    if (wu == null) return;
    @WLD@ w = @UNI@.get().getWorld(wu);
    if (w == null || !w.isAlive()) return;
    if (!this.onWorld) { w.execute(new @PKG@.WgSpawnHome(this.pr, this.step, true)); return; }
    route(w);
  } catch (Throwable t) { @PKG@.WgLog.warn("the Zone 1 login trip failed: " + t); }
}""")
# 2. the events: the FIRST ready of an online session schedules the login trip; a disconnect ends the session
