M(srdy, r"""
public void accept(Object ev) {
  try {
    if (ev instanceof @PDE@) {
      @PR@ q = ((@PDE@) ev).getPlayerRef();
      if (q != null && q.getUuid() != null) @PKG@.WgSpawnHome.SEEN.remove(q.getUuid());
      return;
    }
    if (!(ev instanceof @PRE@)) return;
    @PRE@ e = (@PRE@) ev;
    if (e.getPlayer() == null) return;
    @PR@ p = e.getPlayer().getPlayerRef();
    if (p == null || p.getUuid() == null) return;
    if (@PKG@.WgSpawnHome.SEEN.putIfAbsent(p.getUuid(), Boolean.TRUE) != null) return;
    if (!@PKG@.WgCfg.SPAWN_ON) return;
    @PKG@.WgSpawnHome.schedule(p, 0, @PKG@.WgSpawnHome.FIRST_MS);
  } catch (Throwable t) { }
}""")

# ---------------------------------------------------------------- WgZoneArrive (fix round; 0.7: the skywynn_zones2 world): the first-trip hop. /zone 2-5 while the zone
