M(zarr, r"""
public void accept(Object ev) {
  try {
    if (HOPS.isEmpty()) return;
    @PRE@ e = (@PRE@) ev;
    @REF@ r = e.getPlayerRef();
    if (r == null || e.getPlayer() == null) return;
    @PR@ p = e.getPlayer().getPlayerRef();
    if (p == null || p.getUuid() == null) return;
    String key = p.getUuid().toString();
    if (!HOPS.containsKey(key)) return;
    @ST@ st = r.getStore();
    if (st == null) return;
    Object ext = st.getExternalData();
    if (!(ext instanceof @EST@)) return;
    @WLD@ w = ((@EST@) ext).getWorld();
    if (w == null || !@PKG@.WgZones.WORLDS[@PKG@.WgZones.ZONES2].equals(w.getName())) return;
    long[] h = (long[]) HOPS.remove(key);
    if (h == null || System.currentTimeMillis() > h[1]) return;
    w.execute(new @PKG@.WgZoneArrive(w, r, p, (int) h[0]));
  } catch (Throwable t) { }
}""")
M(zarr, r"""
public void run() {
  try {
    if (this.w == null || !this.w.isAlive() || this.r == null || !this.r.isValid()) return;
    if (@PKG@.WgRZ.closed(this.k)) { @PKG@.WgCmds.tell(this.pr, @PKG@.WgRZ.closedText(this.k)); return; }   // 0.7.10
    @ST@ st = this.r.getStore();
    if (st == null) return;
    @PKG@.WgZ2Gen g = @PKG@.WgZ2Isles.genOf(this.w);
    if (g == null) { @PKG@.WgCmds.tell(this.pr, "-[Zone] Could not move you on - run /zone " + @PKG@.WgZ2Isles.Z_IDS[this.k] + " again."); return; }
    if (g.layoutReady((int) this.w.getWorldConfig().getSeed()) == null) { @PKG@.WgCmds.tell(this.pr, "-[Zone] The islands are still being picked - run /zone " + @PKG@.WgZ2Isles.Z_IDS[this.k] + " again in a few seconds."); return; }
    @TRF@ t = g.landingOf((int) this.w.getWorldConfig().getSeed(), this.k);
    String zl = "the Zone " + @PKG@.WgZ2Isles.Z_IDS[this.k] + " island (" + @PKG@.WgZ2Isles.Z_NAMES[this.k] + ")";
    if (t == null) { @PKG@.WgCmds.tell(this.pr, "-[Zone] This world's seed has no Zone " + @PKG@.WgZ2Isles.Z_IDS[this.k] + " island - you stay on Zone 1. /zone info lists the islands."); return; }
    ((@CA@) st).addComponent(this.r, @TP@.getComponentType(), @TP@.createForPlayer(this.w, t));
    MOVED.incrementAndGet();
    @PKG@.WgCmds.tell(this.pr, "=[Zone] Moving you on to " + zl + "...");
  } catch (Throwable t) {
    @PKG@.WgLog.warn("zone islands: could not move a player on to Zone " + (this.k + 1) + " after the first trip: " + t);
    try { @PKG@.WgCmds.tell(this.pr, "-[Zone] Could not move you on - run /zone " + (this.k + 1) + " again."); } catch (Throwable t2) { }
  }
}""")

