M(here, r"""
public static String spawnHere(@ST@ st, @REF@ ref, @PR@ pr, @WLD@ w) {
  @TRF@ t = @PKG@.WgOpen.here(st, ref);
  if (t == null || t.getPosition() == null) return "-[Zone] Could not read your position.";
  @VEC@ p = t.getPosition();
  @PKG@.WgZ2Gen g = @PKG@.WgZ2Isles.genOf(w);
  if (g == null) return "-[Zone] The zone islands generator is not running on this world - nothing was set.";
  @PKG@.WgZ2Layout L = g.layoutReady((int) w.getWorldConfig().getSeed());
  if (L == null) return "-[Zone] The islands are still being picked from the vanilla map - try again in a few seconds.";
  int ii = @PKG@.WgZ2Isles.member(L, Math.floor(p.x) + 0.5, Math.floor(p.z) + 0.5, new double[1]);
  int zz = 0 - 1;
  if (ii >= 0) zz = ii < L.nMain ? ii : L.zone[ii];
  if (zz != 0) {
    String at = zz < 0 ? "You are over the void." : "You are on Zone " + @PKG@.WgZ2Isles.Z_IDS[zz] + ".";
    return "-[Zone] Stand on the Zone 1 island (or one of its islets) - the server spawn lands there. " + at;
  }
  double y = Math.floor(p.y) + 1.0;
  @R3F@ r = t.getRotation();
  double yaw = r == null ? 0.0 : Math.toDegrees((double) r.y);
  yaw = Math.round(Math.IEEEremainder(yaw, 360.0));
  if (yaw <= -180.0) yaw += 360.0;
  double[] np = new double[] { Math.floor(p.x) + 0.5, y, Math.floor(p.z) + 0.5, yaw };
  String why = @PKG@.WgCfg.spawnCheck(np);
  if (why != null) return "-[Zone] " + why;
  String res = @PKG@.WgCmds.cfgSet("zones.spawnPoint", @PKG@.WgCfg.landingText(np), pr);
  if (res != null && !res.startsWith("-") && !@PKG@.WgCfg.SPAWN_ON) res = res + " ('Zone 1 = server spawn' is OFF in Server Setup > World Gen: /zone 1 lands here; switch it on for first join and /spawn.)";
  return res;
}""")
M(here, r"""
public static String setHere(@ST@ st, @REF@ ref, @PR@ pr, @WLD@ w) {
  int zi = @PKG@.WgZones.islandIndex(w);
  if (zi < 0) return "-[Zone] Stand on the zone island first (/zone 1), then set the landing point.";
  if (zi == @PKG@.WgZones.PROOF) return "-[Zone] The proof world's landing is the vanilla spawn point (its world spawn) - /zone setlanding only moves the Zone 1 landing.";
  if (zi == @PKG@.WgZones.ZONES) return "-[Zone] The 0.6 zone islands world (/zone old6) has no landing point to set - the server spawn's Zone 1 landing lives in the zone islands world: /zone 1, stand on the island, /zone setlanding.";
  if (zi == @PKG@.WgZones.ZONES2) return spawnHere(st, ref, pr, w);
  @TRF@ t = @PKG@.WgOpen.here(st, ref);
  if (t == null || t.getPosition() == null) return "-[Zone] Could not read your position.";
  @VEC@ p = t.getPosition();
  double y = Math.floor(p.y) + 1.0;
  @R3F@ r = t.getRotation();
  double yaw = r == null ? 0.0 : Math.toDegrees((double) r.y);
  yaw = Math.round(Math.IEEEremainder(yaw, 360.0));
  if (yaw <= -180.0) yaw += 360.0;
  double[] np = new double[] { Math.floor(p.x) + 0.5, y, Math.floor(p.z) + 0.5, yaw };
  String why = @PKG@.WgCfg.landingCheck(np, zi);
  if (why != null) return "-[Zone] " + why;
  return @PKG@.WgCmds.cfgSet("landing.point", @PKG@.WgCfg.landingText(np), pr);
}""")
M(here, r"""
public void run() {
  try {
    if (this.pr == null || !this.pr.isValid()) return;
    java.util.UUID wu = this.pr.getWorldUuid();
    @WLD@ w = wu == null ? null : @UNI@.get().getWorld(wu);
    if (w == null || !w.getName().equals(this.worldName)) { @PKG@.WgCmds.tell(this.pr, "-[Zone] You changed worlds before the landing point was set - nothing changed."); return; }
    @REF@ ref = this.pr.getReference();
    if (ref == null) return;
    @ST@ st = ref.getStore();
    if (st == null) return;
    @PKG@.WgCmds.tell(this.pr, setHere(st, ref, this.pr, w));
  } catch (Throwable t) {
    @PKG@.WgLog.warn("landing point action failed: " + t);
    @PKG@.WgCmds.tell(this.pr, "-[Zone] Could not set the landing point - the server log has the details.");
  }
}""")

