# ================================================================= 0.7.10 ZONE RESET + UNDO (research/Zone-Reset-Spec.md 3.3, 3.4, 6)
# (the pick sits here: it needs WgZ2Fn / WgZoneSampler, made further up)
F(z2isl, "public static final int RESET_TRIES = 40;")
F(z2isl, "public static final double RESET_AREA = 0.7;")
# ONE try of the reset pick: zone k on gen g (seed mix(ws, k, g)): the deepest land of its class inside the slot (<= slot blocks from its
# FIRST centre), the 0.7 island there, >= 70 % of its first area, ISLE_ZONE_GAP from every other zone's land; then its islets (the CURRENT
# Server Setup counts). Returns zone k's own layout (main entry k + its islet slots, the other mains not found), or null + why[0].
M(z2isl, r"""
public static @PKG@.WgZ2Layout pickOne(@PKG@.WgZ2Gen gen, @PKG@.WgZ2Layout cur, @PKG@.WgZ2Layout base, int ws, int k, int g, int slot, int[] counts, String[] why) {
  long t0 = System.currentTimeMillis();
  int s2 = @PKG@.WgZSeed.mix(ws, k, g);
  @PKG@.WgZoneSampler smp = new @PKG@.WgZoneSampler(gen.getZonePatternGenerator(s2), s2, gen.getZonePatternProvider().getZones());
  @PKG@.WgZ2Fn hs = new @PKG@.WgZ2Fn(gen, s2, 0, 0);
  int cls = Z_CLS[k];
  double ox = base.cx[k];
  double oz = base.cz[k];
  double R = Z_R[k];
  int half = (slot + (int) R + 512) / STEP;
  int w = 2 * half + 1;
  int bx = (int) Math.floor(ox / STEP) * STEP - half * STEP;
  int bz = (int) Math.floor(oz / STEP) * STEP - half * STEP;
  int[] d = new int[w * w];
  for (int j = 0; j < w; j++) for (int i = 0; i < w; i++) d[j * w + i] = smp.applyAsInt(bx + i * STEP, bz + j * STEP) == cls ? BIG : 0;
  chamfer(d, w, w, 3);
  double[] deps = new double[] { MIN_DEPTH, MIN_DEPTH * 0.5 };
  int bp = 0 - 1;
  for (int di = 0; di < deps.length && bp < 0; di++) {
    double best = 0.0 - 1.0E18;
    for (int p = 0; p < w * w; p++) {
      if (d[p] == 0) continue;
      double x = bx + (p % w) * STEP;
      double z = bz + (p / w) * STEP;
      double dist = Math.sqrt((x - ox) * (x - ox) + (z - oz) * (z - oz));
      if (dist > slot) continue;
      double dep = d[p] * (double) STEP / 3.0;
      if (dep < deps[di]) continue;
      double sc = Math.min(dep, CAP_F * R) - DIST_W * dist;
      if (sc > best) { best = sc; bp = p; }
    }
  }
  if (bp < 0) { why[0] = "gen " + g + ": no deep land of its zone within " + slot + " blocks"; return null; }
  int ck = counts == null || k >= counts.length ? 0 : Math.max(0, Math.min(ISLE_MAX, counts[k]));
  int others = 0;
  for (int i = cur.nMain; i < cur.n; i++) if (cur.zone[i] != k) others++;
  @PKG@.WgZ2Layout T = new @PKG@.WgZ2Layout(cur.nMain + others + ck);
  T.nMain = cur.nMain;
  T.seed = s2;
  T.spx = base.spx;
  T.spz = base.spz;
  T.spawnCls = base.spawnCls;
  for (int i = 0; i < cur.nMain; i++) if (i != k) copyEntry(cur, i, T, i);
  int si = cur.nMain;
  for (int i = cur.nMain; i < cur.n; i++) {
    if (cur.zone[i] == k) continue;
    copyEntry(cur, i, T, si);
    si++;
  }
  T.cx[k] = bx + (bp % w) * STEP;
  T.cz[k] = bz + (bp / w) * STEP;
  T.rad[k] = R;
  T.cls[k] = cls;
  T.cell[k] = CELL;
  T.zone[k] = k;
  T.wob[k] = 1.0;
  T.found[k] = true;
  T.gapUsed[k] = GAP;
  buildIsland(T, k, smp, s2);
  if (!T.found[k] || T.sd[k] == null) { why[0] = "gen " + g + ": the island came out empty"; return null; }
  if ((double) T.area[k] < RESET_AREA * (double) base.area[k]) { why[0] = "gen " + g + ": only " + (100L * T.area[k] / Math.max(1L, base.area[k])) + "% of the first island's area"; return null; }
  for (int j = 0; j < si; j++) {
    if (j == k || !T.found[j] || T.sd[j] == null) continue;
    int zj = j < T.nMain ? j : T.zone[j];
    if (zj == k) continue;
    double gp = boxGap(T, k, T, j);
    if (gp < ISLE_ZONE_GAP) { why[0] = "gen " + g + ": only " + Math.round(gp) + " blocks from Zone " + Z_IDS[zj] + "'s land"; return null; }
  }
  int[] hst = heightStats(T, k, hs);
  T.lowY[k] = hst[1];
  T.hmin[k] = hst[0];
  T.hmax[k] = hst[2];
  for (int q = 0; q < ck; q++) {
    int s = si + q;
    T.zone[s] = k;
    T.cls[s] = cls;
    T.cell[s] = CELL_I;
    T.wob[s] = ISLE_WOB;
    placeIslet(T, s, k, q, smp, hs, s2);
  }
  @PKG@.WgZ2Layout Zl = new @PKG@.WgZ2Layout(T.nMain + ck);
  Zl.nMain = T.nMain;
  Zl.seed = s2;
  Zl.spx = base.spx;
  Zl.spz = base.spz;
  Zl.spawnCls = base.spawnCls;
  copyEntry(T, k, Zl, k);
  for (int q = 0; q < ck; q++) copyEntry(T, si + q, Zl, T.nMain + q);
  Zl.ms = System.currentTimeMillis() - t0;
  return Zl;
}""")
# up to RESET_TRIES generations from g0 (P1: Zone 1 fits nearly always, Zones 2-4 about one seed in six); out[0] = the gen that fitted
M(z2isl, r"""
public static @PKG@.WgZ2Layout pickZone(@PKG@.WgZ2Gen gen, @PKG@.WgZ2Layout cur, @PKG@.WgZ2Layout base, int ws, int k, int g0, int slot, int[] counts, int[] out, String[] why) {
  String last = "";
  for (int t = 0; t < RESET_TRIES; t++) {
    int g = g0 + t;
    String[] w = new String[1];
    @PKG@.WgZ2Layout Z = null;
    try { Z = pickOne(gen, cur, base, ws, k, g, slot, counts, w); } catch (Throwable e) { w[0] = "gen " + g + ": " + e; }
    if (Z != null) { out[0] = g; why[0] = (t + 1) + " seed(s) tried"; return Z; }
    last = w[0];
  }
  why[0] = "no new seed fits Zone " + Z_IDS[k] + " in " + RESET_TRIES + " tries (last: " + last + ") - nothing changed. A bigger 'How far a reset island may move' (Server Setup > World Gen, zones.resetSlot, now " + slot + ", up to 900 blocks) gives it more room";
  return null;
}""")
# the land islands of zone k (main + found islets) - its entry count + area (the plan's text)
M(z2isl, r"""
public static String zoneText(@PKG@.WgZ2Layout L, int k) {
  if (L == null || k < 0 || k >= L.nMain || !L.found[k]) return "no island";
  int isl = 0;
  for (int i = L.nMain; i < L.n; i++) if (L.zone[i] == k && L.found[i]) isl++;
  return Math.round(L.area[k] / 10000.0) / 100.0 + " km2 at " + Math.round(L.cx[k]) + " " + Math.round(L.cz[k]) + ", " + isl + " islets";
}""")
