# copy every chunk blob into <bd>/chunks/, the sha1s into the manifest, then read the copy back and compare; null = ok
M(rz, r"""
public static String backupChunks(@PKG@.WgRStore src, long[] ids, java.nio.file.Path bd, java.util.Properties man) {
  @PKG@.WgRStore dst = new @PKG@.WgRStore(null, null, bd.resolve("chunks"));
  int n = 0;
  int missing = 0;
  long bytes = 0L;
  try {
    for (int i = 0; i < ids.length; i++) {
      byte[] b = src.read(ids[i]);
      if (b == null) { missing++; continue; }
      dst.write(ids[i], b);
      man.setProperty("chunk." + n, ids[i] + " " + sha1(b) + " " + b.length);
      n++;
      bytes = bytes + (long) b.length;
    }
  } catch (Throwable t) { dst.close(); return "copying chunk " + n + ": " + t; }
  dst.close();
  man.setProperty("chunks", String.valueOf(n));
  man.setProperty("bytes", String.valueOf(bytes));
  man.setProperty("missing", String.valueOf(missing));
  @PKG@.WgRStore chk = new @PKG@.WgRStore(null, null, bd.resolve("chunks"));
  try {
    Object[] cl = chunksOf(man);
    long[] ix = (long[]) cl[0];
    String[] sh = (String[]) cl[1];
    for (int i = 0; i < ix.length; i++) {
      byte[] b = chk.read(ix[i]);
      if (b == null || !sha1(b).equals(sh[i])) { chk.close(); return "the backup copy of chunk " + @CHU@.xOfChunkIndex(ix[i]) + " " + @CHU@.zOfChunkIndex(ix[i]) + " did not read back the same"; }
    }
  } catch (Throwable t) { chk.close(); return "reading the backup back: " + t; }
  chk.close();
  return null;
}""")
# the backup's chunks back into a store (sha1 checked on both sides); returns the count, or -1 - i at the first bad one
M(rz, r"""
public static int writeBack(java.util.Properties man, java.nio.file.Path bd, @PKG@.WgRStore dst, String[] err) {
  Object[] cl = chunksOf(man);
  long[] ix = (long[]) cl[0];
  String[] sh = (String[]) cl[1];
  @PKG@.WgRStore src = new @PKG@.WgRStore(null, null, bd.resolve("chunks"));
  int n = 0;
  try {
    for (int i = 0; i < ix.length; i++) {
      if (ix[i] == Long.MIN_VALUE) continue;
      byte[] b = src.read(ix[i]);
      if (b == null || !sha1(b).equals(sh[i])) { err[0] = "the backup's chunk " + i + " is damaged"; src.close(); return 0 - 1 - i; }
      dst.write(ix[i], b);
      byte[] c = dst.read(ix[i]);
      if (c == null || !sha1(c).equals(sh[i])) { err[0] = "chunk " + i + " did not write back the same"; src.close(); return 0 - 1 - i; }
      n++;
    }
  } catch (Throwable t) { err[0] = String.valueOf(t); src.close(); return 0 - 1 - n; }
  src.close();
  return n;
}""")
