# the region files of these chunks: their size share (the plan's backup estimate)
M(rjob, r"""
public static long estimate(long[] all, long[] mine) {
  java.nio.file.Path wf = @PKG@.WgRZ.worldFolder();
  if (wf == null) return 0L;
  java.util.HashMap tot = new java.util.HashMap();
  java.util.HashMap my = new java.util.HashMap();
  for (int i = 0; i < all.length; i++) {
    String n = @PKG@.WgRStore.rname(@CHU@.xOfChunkIndex(all[i]) >> 5, @CHU@.zOfChunkIndex(all[i]) >> 5);
    Integer c = (Integer) tot.get(n);
    tot.put(n, Integer.valueOf(c == null ? 1 : c.intValue() + 1));
  }
  for (int i = 0; i < mine.length; i++) {
    String n = @PKG@.WgRStore.rname(@CHU@.xOfChunkIndex(mine[i]) >> 5, @CHU@.zOfChunkIndex(mine[i]) >> 5);
    Integer c = (Integer) my.get(n);
    my.put(n, Integer.valueOf(c == null ? 1 : c.intValue() + 1));
  }
  long b = 0L;
  java.util.Iterator it = my.keySet().iterator();
  while (it.hasNext()) {
    String n = (String) it.next();
    try {
      long sz = java.nio.file.Files.size(wf.resolve("chunks").resolve(n));
      b = b + sz * (long) ((Integer) my.get(n)).intValue() / (long) Math.max(1, ((Integer) tot.get(n)).intValue());
    } catch (Throwable t) { }
  }
  return b;
}""")
